// Regenerates the two nameGender.generated.ts mirrors from the US Social Security Administration's
// national baby-name counts.
//
// Run by hand (`node scripts/build-name-gender.mjs`) when there's a reason to — a new year of data,
// or a change to the cutoffs below. Once a year at most, and never on a deploy: the app ships the
// generated file, so the guess costs zero network calls and zero AI tokens at runtime.
//
// WHY A DATASET AND NOT A HAND-WRITTEN LIST. The first version of this was ~840 names typed out by
// hand, and the founder's complaint (2026-08-19) was the obvious consequence: "it isn't even
// appropriately guessing if Ben or Braden is a male name, or Bridget or Joelle are female." Ben,
// Braden and Joelle simply weren't on the list, and no amount of adding more names by hand fixes
// the shape of that problem — there are ~105,000 first names in the SSA data and a person is always
// going to think of one nobody typed in. Real counts also answer the question the hand-written list
// could only assert: Willie really is 24% female, Micah really is 89% male, and "Jess" on a birth
// certificate really is 98% male even though almost every adult Jess is a Jessica.
//
// WHERE THE DATA COMES FROM. ssa.gov/oact/babynames/names.zip is the primary source and is US
// government work in the public domain, but it 403s any scripted download, so this reads the
// year-by-year mirror at github.com/askbloom/popular-baby-name-ranking-trends, which is the same
// numbers split into one CSV per year (name, overallRank, genderRank, count, gender). If that
// mirror ever disappears, any copy of the SSA yob*.txt files will do — the aggregation below only
// needs name/count/gender.
//
// THE TWO CUTOFFS, AND WHY THEY'RE WHERE THEY ARE:
//
//   MIN_BIRTHS = 500 — a name has to have been given to at least 500 US babies since 1880 before
//   the data is allowed to speak for it. Below that the split is noise (one family's spelling), and
//   the SSA suppresses anything under 5 per year, so rare names are only partly counted anyway.
//   This is what keeps ~89,000 near-unique names out of the file without keeping out Svetlana.
//
//   MIN_SHARE = 0.90 — at least nine in ten people with the name are that gender. The founder's
//   original ask was to only be asked when the app is under ~75% sure; 90% is the stricter side of
//   that, chosen because the cost is asymmetric — an unanswered name costs one dropdown, and calling
//   someone's mother "his father" is the thing the founder would actually notice. Everything between
//   10% and 90% is left out of both lists, which is how a Jordan or a Casey still gets asked about.

import { writeFile } from 'node:fs/promises'

const FIRST_YEAR = 1880
const LAST_YEAR = 2024
const MIN_BIRTHS = 500
const MIN_SHARE = 0.9
const MIRROR = 'https://raw.githubusercontent.com/askbloom/popular-baby-name-ranking-trends/main/name-rankings'

// Fetched a few years at a time rather than all 145 at once — the mirror is someone's personal
// repo and there's no reason to hammer it.
async function fetchYears() {
  const male = new Map()
  const female = new Map()
  const years = []
  for (let y = FIRST_YEAR; y <= LAST_YEAR; y++) years.push(y)

  for (let i = 0; i < years.length; i += 8) {
    const batch = years.slice(i, i + 8)
    const texts = await Promise.all(
      batch.map(async (y) => {
        const res = await fetch(`${MIRROR}/all-names-${y}.csv`)
        if (!res.ok) throw new Error(`${y}: HTTP ${res.status}`)
        return res.text()
      }),
    )
    for (const text of texts) {
      for (const line of text.split('\n').slice(1)) {
        const row = line.trim()
        if (!row) continue
        const [name, , , count, gender] = row.split(',')
        const n = Number(count)
        if (!name || !Number.isFinite(n)) continue
        const target = gender === 'M' ? male : female
        const key = name.toLowerCase()
        target.set(key, (target.get(key) ?? 0) + n)
      }
    }
    process.stdout.write(`${batch[batch.length - 1]} `)
  }
  process.stdout.write('\n')
  return { male, female }
}

const { male, female } = await fetchYears()

const maleNames = []
const femaleNames = []
let split = 0
let tooRare = 0
for (const name of new Set([...male.keys(), ...female.keys()])) {
  const m = male.get(name) ?? 0
  const f = female.get(name) ?? 0
  const total = m + f
  if (total < MIN_BIRTHS) {
    tooRare += 1
    continue
  }
  const share = m / total
  if (share >= MIN_SHARE) maleNames.push(name)
  else if (share <= 1 - MIN_SHARE) femaleNames.push(name)
  else split += 1
}

// Sorted so a regeneration produces a readable diff instead of a reshuffled file, and so gzip has
// the shared prefixes to work with — sorted order is most of why this compresses to ~40KB.
maleNames.sort()
femaleNames.sort()

const body = `// AUTO-GENERATED by scripts/build-name-gender.mjs on ${new Date().toISOString().slice(0, 10)}.
// Do not edit by hand — re-run the script instead. Overrides go in nameGender.ts, not here.
//
// US Social Security Administration national baby-name counts, ${FIRST_YEAR}–${LAST_YEAR} (US government
// work, public domain). A name is listed when it was given to at least ${MIN_BIRTHS} American babies over
// that span AND at least ${MIN_SHARE * 100}% of them were that gender. Names that are genuinely split —
// Jordan, Casey, Taylor — are in neither list, which is how they keep getting asked about.
//
// Written as one comma-separated string rather than a TS array literal for the same reason
// sportsTeams.generated.ts is: a literal this long makes tsc give up with "union type that is too
// complex to represent" (TS2590). Splitting it costs a millisecond once per page load.

/** ${maleNames.length} names, lowercase, sorted. */
export const MALE_NAMES =
  '${maleNames.join(',')}'

/** ${femaleNames.length} names, lowercase, sorted. */
export const FEMALE_NAMES =
  '${femaleNames.join(',')}'
`

// Byte-identical copies. Deno can't reach across the Vite boundary into src/, so the edge functions
// get their own — same arrangement as kinship.ts, familyRoster.ts and nameGender.ts itself, and
// nameGender.test.ts fails the suite if the two ever drift.
for (const path of ['../src/lib/nameGender.generated.ts', '../supabase/functions/_shared/nameGender.generated.ts']) {
  await writeFile(new URL(path, import.meta.url), body)
}

console.log(`\n${maleNames.length} male + ${femaleNames.length} female names written`)
console.log(`skipped: ${split} too split to call, ${tooRare} under ${MIN_BIRTHS} births`)
